"""Exact ingestion binding over native evaluator evidence, never a score store.

See SYN-3605. The evaluator and raw job_result/events remain their authorities;
an ingestion receipt cannot establish organic delivery, revenue or clout.
"""

from pydantic import Field, model_validator

from .contracts import Contract, ExactReference, Identifier, Text


class EvaluationBinding(Contract):
    task: ExactReference
    panel: ExactReference
    corpus: ExactReference
    model: ExactReference
    harness: ExactReference
    data: tuple[ExactReference, ...] = Field(min_length=1, max_length=128)
    split_manifest: ExactReference
    seeds: tuple[int, ...] = Field(min_length=1, max_length=128)
    configuration: ExactReference
    comparator: ExactReference
    budget_protocol: ExactReference
    overlap_disposition: ExactReference
    evaluator: ExactReference
    scorer_receipt: ExactReference
    native_result: ExactReference
    native_events: ExactReference
    delivered: tuple[ExactReference, ...] = Field(default=(), max_length=1024)
    consumed: tuple[ExactReference, ...] = Field(default=(), max_length=1024)
    consumed_assets: tuple[ExactReference, ...] = Field(default=(), max_length=1024)
    usage_receipts: tuple[ExactReference, ...] = Field(default=(), max_length=128)
    metering: Identifier
    limitations: tuple[Text, ...] = Field(default=(), max_length=128)

    @model_validator(mode="after")
    def exact_consumption(self):
        if not set(self.consumed).issubset(self.delivered):
            raise ValueError("consumed contributions must be delivered exact revisions")
        if any(
            ref.authority != "index" or ref.kind != "contribution"
            for ref in self.delivered
        ):
            raise ValueError("contribution consumption requires exact Index revisions")
        if self.consumed and not self.consumed_assets:
            raise ValueError("consumption requires exact actual asset digests")
        if self.metering not in {"known", "unknown", "not_applicable"}:
            raise ValueError("metering state is unsupported")
        if self.metering == "known" and not self.usage_receipts:
            raise ValueError("known metering requires actual usage receipts")
        if len(set(self.seeds)) != len(self.seeds):
            raise ValueError("seeds must be unique")
        return self
